function myrMobileSuggestionGeometry(rect,viewport){
 const left=viewport.left+8,right=viewport.left+viewport.width-8,top=viewport.top+8,bottom=viewport.top+viewport.height-8;
 const width=Math.max(0,Math.min(Math.max(rect.width,250),right-left));
 const x=Math.max(left,Math.min(rect.left,right-width));
 const below=Math.max(0,bottom-Math.max(top,rect.bottom+4)),above=Math.max(0,Math.min(bottom,rect.top-4)-top);
 const up=below<120&&above>below;
 const height=Math.min(240,up?above:below);
 return {left:x,width,top:up?Math.min(bottom,rect.top-4)-height:Math.max(top,rect.bottom+4),height};
}
