function myrObMatches(q){const terms=String(q||'').trim().toLowerCase().split(/\s+/).filter(Boolean);return MYR_OB_MSIC.map(([code,desc],i)=>({code,desc,i})).filter(x=>terms.every(t=>(x.code+' '+x.desc).toLowerCase().includes(t)))}
function myrObOptions(q){return opt([['','Select business activity'],...myrObMatches(q).map(x=>[String(x.i),x.code+' — '+x.desc])],'')}
function myrObSelect(){const select=$('#ob-msic-select'),entry=select&&select.value!==''?MYR_OB_MSIC[Number(select.value)]:null;$('#ob-msic').value=entry?.[0]||'';$('#ob-msicd').value=entry?.[1]||'';$('#ob-msic-summary').textContent=entry?entry[0]+' — '+entry[1]:'Select the code matching your registered business activity.'}
function myrObSearch(){const q=val('ob-msic-search'),select=$('#ob-msic-select'),hits=myrObMatches(q);select.innerHTML=myrObOptions(q);if(hits.length===1&&hits[0].code===q)select.value=String(hits[0].i);myrObSelect();$('#ob-msic-count').textContent=hits.length?hits.length+' matching activities':'No matching activity. Try another keyword or consult the official list.'}
function myrObSst(){const choice=val('ob-sst-status'),input=$('#ob-sst'),box=$('#ob-sst-wrap');box.hidden=choice!=='yes';input.disabled=choice!=='yes';input.required=choice==='yes';input.value=choice==='no'?'NA':''}
async function myrObSubmit(btn){if(btn.disabled)return;const panel=$('#myr-onboard-fields');for(const el of panel.querySelectorAll('input,select')){if(!el.disabled&&!el.reportValidity())return}myrObSelect();if(!TIN_RE.test(val('ob-tin').toUpperCase()))return toast('Enter a valid Tax Identification Number (TIN).','err');if(!val('ob-msic')||!val('ob-msicd'))return toast('Select your registered business activity.','err');if(val('ob-sst-status')==='yes'&&(!val('ob-sst')||val('ob-sst').toUpperCase()==='NA'))return toast('Enter your SST registration number.','err');btn.disabled=true;try{await saveOnboard()}finally{if(btn.isConnected)btn.disabled=false}}
